<script setup>
import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import SettingsNav from'../../Components/SettingsNav.vue';import UiButton from'../../Components/UiButton.vue';import UiAlert from'../../Components/UiAlert.vue';import{Head,useForm}from'@inertiajs/vue3';import{computed,onBeforeUnmount,onMounted,ref}from'vue'
const p=defineProps({section:String,settings:Object}),positions=[['top_left','Top Left'],['top_right','Top Right'],['bottom_left','Bottom Left'],['bottom_right','Bottom Right'],['bottom_center','Bottom Center'],['center','Center']],input=ref(null),preview=ref(p.settings.logo_url||null),form=useForm({size_percentage:p.settings.size_percentage,position:p.settings.position,logo:null,remove_logo:false})
const style=computed(()=>{const map={top_left:{left:'2%',top:'2%'},top_right:{right:'2%',top:'2%'},bottom_left:{left:'2%',bottom:'2%'},bottom_right:{right:'2%',bottom:'2%'},bottom_center:{left:'50%',bottom:'2%',transform:'translateX(-50%)'},center:{left:'50%',top:'50%',transform:'translate(-50%,-50%)'}};return{...map[form.position],width:`${form.size_percentage}%`}})
function choose(e){const f=e.target.files?.[0];form.clearErrors('logo');if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)){form.setError('logo','The selected image format is not supported.');e.target.value='';return}if(f.size>2097152){form.setError('logo','Please select an image smaller than 2 MB.');e.target.value='';return}if(String(preview.value||'').startsWith('blob:'))URL.revokeObjectURL(preview.value);form.logo=f;form.remove_logo=false;preview.value=URL.createObjectURL(f)}function remove(){if(String(preview.value||'').startsWith('blob:'))URL.revokeObjectURL(preview.value);preview.value=null;form.logo=null;form.remove_logo=true;if(input.value)input.value.value=''}function save(){form.transform(d=>({...d,_method:'put'})).post('/settings/watermark',{forceFormData:true,preserveScroll:true})}function leaving(e){if(form.isDirty){e.preventDefault();e.returnValue=''}}onMounted(()=>addEventListener('beforeunload',leaving));onBeforeUnmount(()=>{removeEventListener('beforeunload',leaving);if(String(preview.value||'').startsWith('blob:'))URL.revokeObjectURL(preview.value)})
</script>
<template><AppShell><Head title="Watermark"/><div class="lp-page"><PageHeader eyebrow="Settings" title="Watermark" description="Configure the studio logo used by Groups with watermarking enabled."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav :section="section"/><form class="lp-card space-y-7 p-5 sm:p-7" @submit.prevent="save"><label class="lp-label" for="watermark-size">Size Range <strong class="ml-2 text-indigo">{{form.size_percentage}}</strong><input id="watermark-size" v-model.number="form.size_percentage" type="range" min="1" max="99" class="mt-3 w-full" :aria-valuenow="form.size_percentage"><small class="text-rose-600">{{form.errors.size_percentage}}</small></label><fieldset><legend class="lp-label">Position</legend><div class="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-3" role="radiogroup"><label v-for="position in positions" :key="position[0]" :class="['flex cursor-pointer items-center gap-2 rounded-xl border p-4 text-sm font-semibold',form.position===position[0]?'border-indigo bg-indigo/5':'border-slate-200']"><input v-model="form.position" type="radio" name="watermark-position" :value="position[0]">{{position[1]}}</label></div><small class="text-rose-600">{{form.errors.position}}</small></fieldset><section><h2 class="lp-label">Logo</h2><div class="mt-3 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5"><div class="relative mx-auto aspect-video max-w-xl overflow-hidden rounded-lg bg-gradient-to-br from-slate-300 to-slate-700"><div class="absolute inset-0 grid place-items-center text-white/50">Watermark preview</div><img v-if="preview" :src="preview" alt="Watermark logo preview" class="absolute h-auto object-contain" :style="style"></div><div class="mt-5 text-center"><p v-if="form.logo" class="mb-3 text-sm font-semibold">{{form.logo.name}}</p><div class="flex flex-wrap justify-center gap-3"><label class="btn-secondary cursor-pointer">Browse<input ref="input" type="file" accept="image/png,image/jpeg,image/webp" class="sr-only" aria-label="Browse for Watermark logo" @change="choose"></label><button v-if="preview" type="button" class="btn-secondary text-rose-700" @click="remove">Remove Logo</button></div><p class="mt-3 text-xs text-slate-500">Upload Logo for Watermark<br>We recommend using PNG format<br>Maximum size allowed is 2 MB</p><small class="text-rose-600" role="alert">{{form.errors.logo}}</small></div></div></section><UiAlert tone="warning">Watermarking activates only for Groups where “Apply watermark” is enabled and a valid studio logo exists. Original/master photos remain unchanged.</UiAlert><UiButton type="submit" :loading="form.processing" :disabled="!form.isDirty">Save</UiButton></form></div></div></AppShell></template>
